/**
 * The frame of a signed-in app around placeholder content. Axes: topbar (full: across the whole shell, inset:
 * over the content column only, none), search (show, hide: the search field of the top bar), sidebar (wide,
 * rail, collapsed: the static collapsed state, twolevel: a rail and a section panel, none: the top bar carries
 * the links), side (start, end), footer (full, inset, none), content (grid, split, list), frame (window: a
 * framed window in a section, page: the whole page). Collapsing the sidebar is a port contract.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { ShellContent } from "../components/shell-content";
import { ShellFooter } from "../components/shell-footer";
import { ShellSidebar } from "../components/shell-sidebar";
import { ShellTopbar } from "../components/shell-topbar";
import { cn, tpl } from "../utils";
import type { ShellNav } from "./dashboard-shell.types";
import type { NavLink } from "./nav-bar.types";

export type DashboardShellProps = {
  id: string;
  title: string;
  level?: 1 | 2;
  nav: ShellNav;
  topbar?: "full" | "inset" | "none";
  search?: "show" | "hide";
  sidebar?: "wide" | "rail" | "collapsed" | "twolevel" | "none";
  side?: "start" | "end";
  footer?: "full" | "inset" | "none";
  content?: "grid" | "split" | "list";
  frame?: "window" | "page";
};

export function DashboardShell({
  id,
  title,
  level = 2,
  nav,
  topbar = "full",
  search = "show",
  sidebar = "wide",
  side = "start",
  footer = "none",
  content = "grid",
  frame = "window",
}: DashboardShellProps) {
  const titleId = tpl("{0}-title", id);
  return (
    <Block
      tag="section"
      className={(((frame as string) === "window") ? "bg-background py-12" : "bg-background")}
      id={id}
      aria-labelledby={titleId}
      data-testid="dashboard-shell"
      data-topbar={topbar}
      data-sidebar={sidebar}
      data-footer={footer}
    >
      <Box className={(((frame as string) === "window") ? "mx-auto w-full max-w-6xl px-4" : "")}>
        <Box
          className={cn(
            "flex flex-col overflow-hidden bg-background",
            (((frame as string) === "window") ? "min-h-160 rounded border border-border" : "min-h-screen")
          )}
          data-testid="window"
        >
          {((topbar as string) === "full") ? (
            <ShellTopbar
              nav={nav}
              brand="show"
              links={(((sidebar as string) === "none") ? "show" : "hide")}
              search={search}
            />
          ) : null}
          <Box className={cn("flex min-h-0 flex-1", (((side as string) === "end") ? "flex-row-reverse" : ""))}>
            {((sidebar as string) !== "none") ? (
              <ShellSidebar nav={nav} mode={sidebar} side={side} brand={(((topbar as string) === "full") ? "hide" : "show")} />
            ) : null}
            <Box className="flex min-w-0 flex-1 flex-col">
              {((topbar as string) === "inset") ? (
                <ShellTopbar
                  nav={nav}
                  brand={(((sidebar as string) === "none") ? "show" : "hide")}
                  links={(((sidebar as string) === "none") ? "show" : "hide")}
                  search={search}
                />
              ) : null}
              <ShellContent title={title} titleId={titleId} level={level} content={content} />
              {((footer as string) === "inset") ? (
                <ShellFooter nav={nav} place="inset" />
              ) : null}
            </Box>
          </Box>
          {((footer as string) === "full") ? (
            <ShellFooter nav={nav} place="full" />
          ) : null}
        </Box>
      </Box>
    </Block>
  );
}

